const config = $('Config').item.json;

return [{
  json: {
    query: `
      query GetUpcomingEvents($from: String!, $to: String!, $first: Int, $after: String) {
        events(
          filters: [
            { field: timeZonedStart, operation: ge, value: $from }
            { field: timeZonedStart, operation: le, value: $to }
            { field: lifecycleState, operation: eq, value: "published" }
          ]
          orderBy: [{ field: timeZonedStart, direction: asc }]
          first: $first
          after: $after
        ) {
          pageInfo {
            hasNextPage
            endCursor
          }
          edges {
            node {
              id
              code
              title
              timeZonedStart
              bookedPlaces
              minPlaces
            }
          }
        }
      }
    `,
    variables: {
      from: DateTime.now().plus({ days: config.TWO_WEEK_FROM_DAYS }).toISO(),
      to: DateTime.now().plus({ days: config.FOUR_WEEK_TO_DAYS }).toISO(),
      first: config.PAGE_SIZE,
      after: null
    }
  }
}];

const config = $('Config').item.json;
const edges = $input.all().flatMap(i => i.json?.data?.events?.edges ?? []) // one item per page;

const now = DateTime.now();
const fourWeekFrom = now.plus({ days: config.FOUR_WEEK_FROM_DAYS });
const fourWeekTo   = now.plus({ days: config.FOUR_WEEK_TO_DAYS });
const twoWeekFrom  = now.plus({ days: config.TWO_WEEK_FROM_DAYS });
const twoWeekTo    = now.plus({ days: config.TWO_WEEK_TO_DAYS });

const toCancel = [];

for (const edge of edges) {
  const event        = edge.node;
  const start        = DateTime.fromISO(event.timeZonedStart);
  const bookedPlaces = event.bookedPlaces ?? 0;
  const minPlaces    = event.minPlaces    ?? 0;

  // 4-week rule: cancel if fewer than 3 registrations
  if (start >= fourWeekFrom && start <= fourWeekTo) {
    if (bookedPlaces < config.FOUR_WEEK_MIN_REGS) {
      toCancel.push({
        ...event,
        bookedPlaces,
        cancellationRule: `4-week rule (${bookedPlaces} registrations, threshold < ${config.FOUR_WEEK_MIN_REGS})`
      });
      continue;
    }
  }

  // 2-week rule: cancel if below 50% of minimum required places
  if (start >= twoWeekFrom && start <= twoWeekTo) {
    if (minPlaces > 0 && bookedPlaces < minPlaces * 0.5) {
      toCancel.push({
        ...event,
        bookedPlaces,
        cancellationRule: `2-week rule (${bookedPlaces}/${minPlaces} min = ${Math.round(bookedPlaces / minPlaces * 100)}%)`
      });
    }
  }
}

if (toCancel.length === 0) {
  return [{ json: { _noResults: true } }];
}

return [{ json: { events: toCancel, count: toCancel.length } }];

const config = $('Config').item.json;
const { events, count } = $input.first().json;

// ---- One-time approval tokens --------------------------------------------
// Each Cancel link carries a random token. The token is kept in this
// workflow's static data (shared with the Approval Webhook below) and is
// checked, then deleted, when the cancellation is confirmed.
// Static data is only saved for production runs (active workflow), so links
// from a manual test run will show "link invalid or expired".
const store = $getWorkflowStaticData('global');
const tokens = { ...(store.approvalTokens || {}) };
const nowMs = Date.now();
for (const [t, entry] of Object.entries(tokens)) {
  if (!entry || entry.expires < nowMs) delete tokens[t];
}
const ttlMs = (config.APPROVAL_LINK_TTL_DAYS ?? 7) * 24 * 60 * 60 * 1000;
const randomToken = () => {
  try {
    if (globalThis.crypto && typeof globalThis.crypto.randomUUID === 'function') {
      return (globalThis.crypto.randomUUID() + globalThis.crypto.randomUUID()).replace(/-/g, '');
    }
  } catch (e) { /* fall back below */ }
  let t = '';
  for (let i = 0; i < 6; i++) t += Math.random().toString(36).slice(2);
  return t + nowMs.toString(36);
};

const rows = events.map(e => {
  const date      = DateTime.fromISO(e.timeZonedStart).toFormat('dd/MM/yyyy HH:mm');
  const numericId = Buffer.from(e.id, 'base64').toString('utf-8').split(':')[1];
  const eventUrl  = `https://${config.ADM_INSTANCE_SUBDOMAIN}.administrateapp.com/beta#/events/events/${numericId}`;
  const token     = randomToken();
  tokens[token] = {
    eventId: e.id,
    code: e.code,
    title: e.title,
    start: e.timeZonedStart,
    rule: e.cancellationRule,
    expires: nowMs + ttlMs
  };
  // Opening this link only shows a confirmation page; nothing is cancelled until the button on that page is pressed.
  const cancelUrl = `${config.EXECUTOR_WEBHOOK_URL}?eventId=${encodeURIComponent(e.id)}&token=${encodeURIComponent(token)}`;
  return `
    <tr>
      <td style="padding:8px;border:1px solid #ddd">${e.code}</td>
      <td style="padding:8px;border:1px solid #ddd">${e.title}</td>
      <td style="padding:8px;border:1px solid #ddd">${date}</td>
      <td style="padding:8px;border:1px solid #ddd;text-align:center">${e.bookedPlaces}</td>
      <td style="padding:8px;border:1px solid #ddd">${e.cancellationRule}</td>
      <td style="padding:8px;border:1px solid #ddd;text-align:center">
        <a href="${eventUrl}" style="color:#2980b9;font-size:13px;font-weight:bold">${numericId}</a>
      </td>
      <td style="padding:8px;border:1px solid #ddd;text-align:center">
        <a href="${cancelUrl}"
           style="background:#c0392b;color:white;padding:8px 16px;text-decoration:none;border-radius:4px;display:inline-block;font-size:13px;font-weight:bold;white-space:nowrap">
          Cancel Event
        </a>
      </td>
    </tr>`;
}).join('');

const html = `
<!DOCTYPE html>
<html>
<body style="font-family:Arial,sans-serif;max-width:960px;margin:0 auto">
  <h2 style="color:#333">Event Cancellation Review</h2>
  <p>The following <strong>${count} event(s)</strong> do not meet the minimum attendance threshold and are eligible for cancellation.</p>
  <p>Use the individual <strong>Cancel Event</strong> button for each one you want to cancel. The button opens a confirmation page &mdash; the event is only cancelled when you confirm there. Links expire after ${config.APPROVAL_LINK_TTL_DAYS ?? 7} day(s) and can be used once.</p>
  <table style="border-collapse:collapse;width:100%;margin-bottom:24px">
    <thead>
      <tr style="background:#f0f0f0">
        <th style="padding:8px;border:1px solid #ddd;text-align:left">Code</th>
        <th style="padding:8px;border:1px solid #ddd;text-align:left">Title</th>
        <th style="padding:8px;border:1px solid #ddd;text-align:left">Start Date</th>
        <th style="padding:8px;border:1px solid #ddd;text-align:center">Registrations</th>
        <th style="padding:8px;border:1px solid #ddd;text-align:left">Rule Applied</th>
        <th style="padding:8px;border:1px solid #ddd;text-align:center">Event ID</th>
        <th style="padding:8px;border:1px solid #ddd;text-align:center">Action</th>
      </tr>
    </thead>
    <tbody>${rows}</tbody>
  </table>
  <p style="color:#999;font-size:12px">
    Each event is cancelled independently — cancelling one does not affect the others.
    The cancellation rules are re-evaluated at the moment you click, so any event that has received new
    registrations since this email was sent will not be cancelled.
  </p>
</body>
</html>`;

// Save the new tokens (reassign so n8n persists the change)
store.approvalTokens = tokens;

return [{
  json: {
    html,
    subject: `[Action Required] ${count} Event(s) Eligible for Cancellation – ${DateTime.now().toFormat('dd/MM/yyyy')}`
  }
}];

