// After the Merge, $json contains both:
//   - original event data (id, staffEdges, learnerEdges, etc.) from input 0
//   - cancel API response (data.event.update) from input 1
// No back-references needed — everything is in $json directly.
const config = $('Config1').item.json;
const data = $input.first().json;

// Log any cancel errors but don't stop the pipeline
const cancelErrors = data?.data?.event?.update?.errors ?? [];
if (cancelErrors.length > 0) {
  console.error('Cancel errors for event', data.id, JSON.stringify(cancelErrors));
}

const staffEdges         = data.staffEdges  ?? [];
const learnerEdges       = data.learnerEdges ?? [];
const instructorRoleName = (config.INSTRUCTOR_ROLE_NAME ?? 'Instructor').toLowerCase();

const instructorContactIds = staffEdges
  .filter(e => e.node.staffRole?.name?.toLowerCase() === instructorRoleName)
  .map(e => e.node.contact?.id)
  .filter(Boolean);

const participantContactIds = learnerEdges
  .map(e => e.node.contact?.id)
  .filter(Boolean);

const learnerIds = learnerEdges.map(e => e.node.id);

return [{
  json: {
    eventId:               data.id,
    eventCode:             data.code,
    eventTitle:            data.title,
    eventStart:            data.timeZonedStart,
    instructorContactIds,
    participantContactIds,
    learnerIds,
    cancelStatus: cancelErrors.length > 0 ? 'error' : 'cancelled'
  }
}];

