const config = $('Config1').item.json;

return [{
  json: {
    query: `
      query GetUpcomingEvents($from: String!, $to: String!, $first: Int, $after: String) {
        events(
          filters: [
            { field: timeZonedStart, operation: ge, value: $from }
            { field: timeZonedStart, operation: le, value: $to }
            { field: lifecycleState, operation: eq, value: "published" }
          ]
          orderBy: [{ field: timeZonedStart, direction: asc }]
          first: $first
          after: $after
        ) {
          pageInfo {
            hasNextPage
            endCursor
          }
          edges {
            node {
              id
              code
              title
              timeZonedStart
              bookedPlaces
              minPlaces
              staff {
                edges {
                  node {
                    staffRole { name }
                    contact { id }
                  }
                }
              }
              learners {
                edges {
                  node {
                    id
                    contact { id }
                  }
                }
              }
            }
          }
        }
      }
    `,
    variables: {
      from: DateTime.now().plus({ days: config.TWO_WEEK_FROM_DAYS }).toISO(),
      to: DateTime.now().plus({ days: config.FOUR_WEEK_TO_DAYS }).toISO(),
      first: config.PAGE_SIZE,
      after: null
    }
  }
}];

// Re-runs rules at approval time — protects events that gained
// registrations between the review email and the approval click.
// Also filters to only the event whose approval token was verified.

const config       = $('Config1').item.json;
const targetId     = $('Verify Approval Token').first().json.eventId ?? null;
const edges        = $input.all().flatMap(i => i.json?.data?.events?.edges ?? []) // one item per page;

const now = DateTime.now();
const fourWeekFrom = now.plus({ days: config.FOUR_WEEK_FROM_DAYS });
const fourWeekTo   = now.plus({ days: config.FOUR_WEEK_TO_DAYS });
const twoWeekFrom  = now.plus({ days: config.TWO_WEEK_FROM_DAYS });
const twoWeekTo    = now.plus({ days: config.TWO_WEEK_TO_DAYS });

const toCancel = [];

// Never fall back to "all qualifying events": a verified event id is required.
if (!targetId) {
  return [{ json: { _noEvents: true } }];
}

for (const edge of edges) {
  const event        = edge.node;

  // Only process the event that was requested
  if (event.id !== targetId) continue;

  const start        = DateTime.fromISO(event.timeZonedStart);
  const bookedPlaces = event.bookedPlaces ?? 0;
  const minPlaces    = event.minPlaces    ?? 0;

  const staffEdges   = event.staff?.edges   ?? [];
  const learnerEdges = event.learners?.edges ?? [];

  const qualified =
    (start >= fourWeekFrom && start <= fourWeekTo && bookedPlaces < config.FOUR_WEEK_MIN_REGS) ||
    (start >= twoWeekFrom  && start <= twoWeekTo  && minPlaces > 0 && bookedPlaces < minPlaces * 0.5);

  if (qualified) {
    toCancel.push({
      json: {
        id:             event.id,
        code:           event.code,
        title:          event.title,
        timeZonedStart: event.timeZonedStart,
        bookedPlaces,
        staffEdges,
        learnerEdges
      }
    });
  }
}

if (toCancel.length === 0) {
  return [{ json: { _noEvents: true } }];
}

return toCancel;

const data = $input.first().json;
const config = $('Config1').item.json;
const contactIds = data.instructorContactIds ?? [];

return [{ json: {
  ...data,
  _contactIds: contactIds,
  _templateId: config.INSTRUCTOR_TEMPLATE_ID,
  _sendingAddressId: config.SENDING_ADDRESS_ID,
  _skip: contactIds.length === 0
}}];

const data = $('Build Notification Data').first().json;
const config = $('Config1').item.json;
const contactIds = data.participantContactIds ?? [];

return [{ json: {
  ...data,
  _contactIds: contactIds,
  _templateId: config.PARTICIPANT_TEMPLATE_ID,
  _sendingAddressId: config.SENDING_ADDRESS_ID,
  _skip: contactIds.length === 0
}}];

const data = $input.first().json;
const isError = data.cancelStatus === 'error';
const css = '*{box-sizing:border-box;margin:0;padding:0}body{font-family:Arial,sans-serif;background:#f4f4f4;display:flex;align-items:center;justify-content:center;min-height:100vh}.card{background:#fff;border-radius:8px;box-shadow:0 2px 12px rgba(0,0,0,0.1);padding:48px 40px;text-align:center;max-width:440px;width:90%}.icon{font-size:52px;margin-bottom:20px}.title{color:#222;font-size:22px;font-weight:bold;margin-bottom:10px}.msg{color:#555;font-size:15px;line-height:1.6}.note{margin-top:20px;color:#999;font-size:13px}';
const wrap = (icon, title, msg) =>
  `<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Event Cancellation</title><style>${css}</style></head><body><div class="card"><div class="icon">${icon}</div><div class="title">${title}</div><div class="msg">${msg}</div><div class="note">You can close this window.</div></div></body></html>`;
const responseHtml = isError
  ? wrap('&#10060;', 'Cancellation Failed', 'There was a problem cancelling this event in Administrate. Please check the n8n execution logs and cancel it manually if needed.')
  : wrap('&#9989;', 'Cancellation Confirmed', 'The event cancellation is being processed. Instructors and participants will be notified shortly.');
return [{ json: { ...data, responseHtml } }];

// GET handler: shows a confirmation page. It has NO side effects, so email
// link scanners that pre-fetch the link cannot cancel anything.
const q      = $input.first().json.query ?? {};
const token  = String(q.token ?? '');
const store  = $getWorkflowStaticData('global');
const entry  = (store.approvalTokens ?? {})[token];
const valid  = !!entry && entry.eventId === q.eventId && entry.expires > Date.now();

const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const css = '*{box-sizing:border-box;margin:0;padding:0}body{font-family:Arial,sans-serif;background:#f4f4f4;display:flex;align-items:center;justify-content:center;min-height:100vh}.card{background:#fff;border-radius:8px;box-shadow:0 2px 12px rgba(0,0,0,0.1);padding:40px;text-align:center;max-width:480px;width:90%}.title{color:#222;font-size:22px;font-weight:bold;margin-bottom:12px}.msg{color:#555;font-size:15px;line-height:1.6;margin-bottom:8px}.meta{color:#333;font-size:14px;text-align:left;background:#f8f8f8;border-radius:6px;padding:12px 16px;margin:16px 0}.btn{background:#c0392b;color:#fff;border:none;border-radius:4px;padding:12px 24px;font-size:15px;font-weight:bold;cursor:pointer}.note{margin-top:20px;color:#999;font-size:13px}';
const wrap = (inner) => `<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex"><title>Event Cancellation</title><style>${css}</style></head><body><div class="card">${inner}</div></body></html>`;

let responseHtml;
let statusCode = 200;
if (!valid) {
  statusCode = 403;
  responseHtml = wrap(`<div class="title">Link invalid or expired</div><div class="msg">This cancellation link is not valid any more. It may already have been used, or it has expired. No changes have been made.</div><div class="note">Wait for the next review email, or cancel the event in Administrate.</div>`);
} else {
  const start = entry.start ? DateTime.fromISO(entry.start).toFormat('dd/MM/yyyy HH:mm') : '';
  // No "action" attribute: the form posts back to this same webhook URL.
  responseHtml = wrap(`<div class="title">Cancel this event?</div>
<div class="meta"><strong>${esc(entry.code)}</strong> &ndash; ${esc(entry.title)}<br>Start: ${esc(start)}<br>Rule: ${esc(entry.rule)}</div>
<div class="msg">The cancellation rules are checked again when you confirm. Instructors and learners will be emailed and every registration will be cancelled.</div>
<form method="POST">
  <input type="hidden" name="eventId" value="${esc(entry.eventId)}">
  <input type="hidden" name="token" value="${esc(token)}">
  <button type="submit" class="btn">Confirm cancellation</button>
</form>
<div class="note">If you did not mean to cancel this event, close this window.</div>`);
}

return [{ json: { responseHtml, statusCode } }];

// POST handler: verifies the one-time token from the confirmation page.
// A valid token is deleted straight away so the same link cannot be replayed.
const body    = $input.first().json.body ?? {};
const eventId = String(body.eventId ?? '');
const token   = String(body.token ?? '');
const store   = $getWorkflowStaticData('global');
const tokens  = { ...(store.approvalTokens ?? {}) };
const entry   = tokens[token];
const valid   = !!eventId && !!entry && entry.eventId === eventId && entry.expires > Date.now();

if (valid) {
  delete tokens[token];
  store.approvalTokens = tokens; // reassign so n8n persists the change
}

return [{ json: { valid, eventId: valid ? eventId : null } }];
